c8c9-fffd-5cb8-a5dc-779339f6747c","scope":"platform","organization_id":null,"chapter_id":null,"kind":"quote","locale":"en","locale_state":"draft","title":"Negotiation wisdom","body":"If you don't know where you'll go if this deal falls apart, you're negotiating blind.","attribution":"Negotiation wisdom","source":"","rights_note":"","review_note":"","bullets":[],"direction":"","topics":["labor"],"audience":"all","tone":"","learning_outcome":"","factual_claims":false,"priority":41,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-240","donor_type":"Quote","donor_category":"Labor","donor_audience":"All","donor_placement":"Inline Quote","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"Q(240, \"If you don't know where you'll go if this deal falls apart, you're negotiating blind.\", 'Negotiation wisdom')","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"c6b212de-1ddc-548d-a161-ea93f32c589e","scope":"platform","organization_id":null,"chapter_id":null,"kind":"quote","locale":"en","locale_state":"draft","title":"Negotiation wisdom","body":"Effective negotiators don't have one style — they adapt to the situation.","attribution":"Negotiation wisdom","source":"","rights_note":"","review_note":"","bullets":[],"direction":"","topics":["labor"],"audience":"all","tone":"","learning_outcome":"","factual_claims":false,"priority":42,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-241","donor_type":"Quote","donor_category":"Labor","donor_audience":"All","donor_placement":"Inline Quote","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"Q(241, \"Effective negotiators don't have one style — they adapt to the situation.\", 'Negotiation wisdom')","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"0d3acb99-529f-565d-a042-c2d65cb642b3","scope":"platform","organization_id":null,"chapter_id":null,"kind":"quote","locale":"en","locale_state":"draft","title":"Labor tradition","body":"Arbitration is justice delivered by the chosen, not the appointed.","attribution":"Labor tradition","source":"","rights_note":"","review_note":"","bullets":[],"direction":"","topics":["labor"],"audience":"all","tone":"","learning_outcome":"","factual_claims":false,"priority":43,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-242","donor_type":"Quote","donor_category":"Labor","donor_audience":"All","donor_placement":"Inline Quote","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"Q(242, 'Arbitration is justice delivered by the chosen, not the appointed.',          'Labor tradition')","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"6ec53686-36c7-595f-a7f7-444c7fc316e8","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Authority Gradient: Ask for the Rule, Not the Tone","body":"When management or union leadership carries more title, more history, or more control, the risk is not only bad decisions. The risk is silence. A steward's job is to bring the conversation back to the contract, the policy, the facts, and the member's rights.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Ask what rule, directive, or contract language is actually being relied on.","Separate intimidating tone from actual authority.","Follow up in writing so the record is clearer than the pressure in the room.","Escalate when the answer stays vague or keeps moving."],"direction":"","topics":["rights"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":1,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-300","donor_type":"Mini-Lesson","donor_category":"Rights","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(300, 'Stewards', 'Rights', 'Authority Gradient: Ask for the Rule, Not the Tone',\r\n    'When management or union leadership carries more title, more history, or more control, the risk is not only bad decisions. The risk is silence. A steward\\'s job is to bring the conversation back to the contract, the policy, the facts, and the member\\'s rights.',\r\n    [\r\n      'Ask what rule, directive, or contract language is actually being relied on.',\r\n      'Separate intimidating tone from actual authority.',\r\n      'Follow up in writing so the record is clearer than the pressure in the room.',\r\n      'Escalate when the answer stays vague or keeps moving.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"b67600ff-6222-5f4b-a600-786d6fdde265","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Weingarten Triage: The First 5 Minutes Matter","body":"The first few minutes of a possible discipline meeting shape everything that follows. Slow the meeting down, confirm whether discipline is on the table, and make sure the member understands they do not have to guess their way through management's questions alone.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Ask whether the meeting could lead to discipline before the substance starts.","State the representation request plainly and early.","Get the member to stop volunteering details before you understand the issue.","Take notes on who was present, what was said, and what documents were referenced."],"direction":"","topics":["grievance"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":2,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-301","donor_type":"Mini-Lesson","donor_category":"Grievance","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(301, 'Stewards', 'Grievance', 'Weingarten Triage: The First 5 Minutes Matter',\r\n    'The first few minutes of a possible discipline meeting shape everything that follows. Slow the meeting down, confirm whether discipline is on the table, and make sure the member understands they do not have to guess their way through management\\'s questions alone.',\r\n    [\r\n      'Ask whether the meeting could lead to discipline before the substance starts.',\r\n      'State the representation request plainly and early.',\r\n      'Get the member to stop volunteering details before you understand the issue.',\r\n      'Take notes on who was present, what was said, and what documents were referenced.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"7282dc37-cb45-5e51-a6f0-531c3d41eb71","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Documentation Discipline: Notes That Actually Help","body":"Good steward notes are not a diary. They are a decision tool. Write down who said what, what management relied on, what the member reported, and what still needs to be confirmed so the next step is evidence-driven instead of memory-driven.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Capture dates, names, directives, deadlines, and missing facts.","Separate direct quotes from your impressions.","Track what documents were requested and whether they were produced.","End every note with the next action and the deadline for it."],"direction":"","topics":["general"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":3,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-302","donor_type":"Mini-Lesson","donor_category":"General","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(302, 'Stewards', 'General', 'Documentation Discipline: Notes That Actually Help',\r\n    'Good steward notes are not a diary. They are a decision tool. Write down who said what, what management relied on, what the member reported, and what still needs to be confirmed so the next step is evidence-driven instead of memory-driven.',\r\n    [\r\n      'Capture dates, names, directives, deadlines, and missing facts.',\r\n      'Separate direct quotes from your impressions.',\r\n      'Track what documents were requested and whether they were produced.',\r\n      'End every note with the next action and the deadline for it.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"eb565417-0c18-5fd0-a74d-3525d7d8899c","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Escalation Without Drama","body":"Escalation is not about sounding bigger. It is about moving the issue to the next level when facts, deadlines, or member harm require it. Calm escalation protects credibility and makes it harder for management to frame the union as emotional or unprepared.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Escalate when deadlines are at risk, facts are being withheld, or retaliation is possible.","State what you asked for, what you received, and what is still missing.","Use written summaries so the issue does not reset in every new meeting.","Keep the tone steady even when the stakes are not."],"direction":"","topics":["negotiation"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":4,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-303","donor_type":"Mini-Lesson","donor_category":"Negotiation","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(303, 'Stewards', 'Negotiation', 'Escalation Without Drama',\r\n    'Escalation is not about sounding bigger. It is about moving the issue to the next level when facts, deadlines, or member harm require it. Calm escalation protects credibility and makes it harder for management to frame the union as emotional or unprepared.',\r\n    [\r\n      'Escalate when deadlines are at risk, facts are being withheld, or retaliation is possible.',\r\n      'State what you asked for, what you received, and what is still missing.',\r\n      'Use written summaries so the issue does not reset in every new meeting.',\r\n      'Keep the tone steady even when the stakes are not.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"f7efb339-e734-5ed8-a495-a669d87d834c","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"How to Raise Internal Union Concerns Respectfully","body":"A strong union needs stewards who can disagree without splintering the work. When a strategy or instruction feels off, raise the concern in a way that keeps the focus on member impact, consistency, and shared accountability.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Ask whether the decision is required by contract, bylaws, past practice, or strategy.","Describe the risk to members instead of arguing from ego.","Ask for written guidance when stewards are being told different things.","Treat respectful disagreement as part of solidarity, not a threat to it."],"direction":"","topics":["general"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":5,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-304","donor_type":"Mini-Lesson","donor_category":"General","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(304, 'Stewards', 'General', 'How to Raise Internal Union Concerns Respectfully',\r\n    'A strong union needs stewards who can disagree without splintering the work. When a strategy or instruction feels off, raise the concern in a way that keeps the focus on member impact, consistency, and shared accountability.',\r\n    [\r\n      'Ask whether the decision is required by contract, bylaws, past practice, or strategy.',\r\n      'Describe the risk to members instead of arguing from ego.',\r\n      'Ask for written guidance when stewards are being told different things.',\r\n      'Treat respectful disagreement as part of solidarity, not a threat to it.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"df4b903a-9157-5fff-a652-1d42467af44a","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Your First Call to a Steward","body":"You do not need a perfect legal theory before contacting your steward. What helps most is a simple, clear record of what happened, who was involved, when it happened, and what management said or did. That gives your steward something concrete to work from right away.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Write down dates, names, and the exact issue before you call or message.","Save emails, screenshots, schedule changes, and written instructions.","Say whether discipline, leave, workload, safety, or pay is involved.","Reach out early. Problems are easier to fix before deadlines close in."],"direction":"","topics":["rights"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":6,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-305","donor_type":"Mini-Lesson","donor_category":"Rights","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(305, 'Members', 'Rights', 'Your First Call to a Steward',\r\n    'You do not need a perfect legal theory before contacting your steward. What helps most is a simple, clear record of what happened, who was involved, when it happened, and what management said or did. That gives your steward something concrete to work from right away.',\r\n    [\r\n      'Write down dates, names, and the exact issue before you call or message.',\r\n      'Save emails, screenshots, schedule changes, and written instructions.',\r\n      'Say whether discipline, leave, workload, safety, or pay is involved.',\r\n      'Reach out early. Problems are easier to fix before deadlines close in.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"1f323168-368c-50ce-ade8-4af886e9ed37","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Weingarten Rights in Plain Language","body":"If management wants to question you in a way that could lead to discipline, you can ask for union representation. That does not make you uncooperative. It means you are protecting your rights and making sure the meeting is fair.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["You have to ask for representation; management does not have to offer it first.","This applies when the meeting could reasonably lead to discipline.","Once you ask, stop answering until representation is handled.","Tell your steward what the meeting was about and who called it."],"direction":"","topics":["rights"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":7,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-306","donor_type":"Mini-Lesson","donor_category":"Rights","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(306, 'Members', 'Rights', 'Weingarten Rights in Plain Language',\r\n    'If management wants to question you in a way that could lead to discipline, you can ask for union representation. That does not make you uncooperative. It means you are protecting your rights and making sure the meeting is fair.',\r\n    [\r\n      'You have to ask for representation; management does not have to offer it first.',\r\n      'This applies when the meeting could reasonably lead to discipline.',\r\n      'Once you ask, stop answering until representation is handled.',\r\n      'Tell your steward what the meeting was about and who called it.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"b2dfd415-e80f-54ec-afde-66ad22e8dfc6","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"PIP, Accuracy Notice, or Coaching: What to Do First","body":"When management raises performance concerns, your first job is not to argue every point on the spot. Your first job is to slow the process down, collect the documents, preserve the timeline, and get union support before the story gets locked in one-sided terms.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Ask for the notice, metrics, examples, and expectations in writing.","Save your own records, workload context, and prior communications.","Do not guess or fill in gaps for management during the meeting.","Contact your steward quickly if the issue could affect discipline or evaluation."],"direction":"","topics":["grievance"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":8,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-307","donor_type":"Mini-Lesson","donor_category":"Grievance","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(307, 'Members', 'Grievance', 'PIP, Accuracy Notice, or Coaching: What to Do First',\r\n    'When management raises performance concerns, your first job is not to argue every point on the spot. Your first job is to slow the process down, collect the documents, preserve the timeline, and get union support before the story gets locked in one-sided terms.',\r\n    [\r\n      'Ask for the notice, metrics, examples, and expectations in writing.',\r\n      'Save your own records, workload context, and prior communications.',\r\n      'Do not guess or fill in gaps for management during the meeting.',\r\n      'Contact your steward quickly if the issue could affect discipline or evaluation.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"227ab955-1dc9-5548-a576-9e0b8256f504","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"What a Grievance Is and Is Not","body":"A grievance is not just a complaint that something felt unfair. A grievance is a contract-enforcement process. It is used when the employer may have violated the agreement, past practice, or a rule that can be challenged through the union process.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["A grievance usually depends on a rule, contract clause, or enforceable workplace obligation.","Not every bad situation is a grievance, but many are still worth raising early.","Deadlines matter, so bring the issue to your steward promptly.","Even when the path is informal at first, documentation still matters."],"direction":"","topics":["grievance"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":9,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-308","donor_type":"Mini-Lesson","donor_category":"Grievance","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(308, 'Members', 'Grievance', 'What a Grievance Is and Is Not',\r\n    'A grievance is not just a complaint that something felt unfair. A grievance is a contract-enforcement process. It is used when the employer may have violated the agreement, past practice, or a rule that can be challenged through the union process.',\r\n    [\r\n      'A grievance usually depends on a rule, contract clause, or enforceable workplace obligation.',\r\n      'Not every bad situation is a grievance, but many are still worth raising early.',\r\n      'Deadlines matter, so bring the issue to your steward promptly.',\r\n      'Even when the path is informal at first, documentation still matters.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"c8337635-0119-51d3-a5a2-68ad2133b751","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Build the Record Before the Story Gets Fixed","body":"Management records events quickly. Members should too. A simple record of dates, directives, witnesses, and documents can make the difference between a vague complaint and a defendable case when memories start shifting later.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Keep screenshots, emails, schedules, and written instructions together.","Write down what happened while it is still fresh.","Note who saw it, who said it, and whether anyone followed up.","Bring the record to your steward so they can see the timeline, not just the conclusion."],"direction":"","topics":["general"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":10,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-309","donor_type":"Mini-Lesson","donor_category":"General","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(309, 'Members', 'General', 'Build the Record Before the Story Gets Fixed',\r\n    'Management records events quickly. Members should too. A simple record of dates, directives, witnesses, and documents can make the difference between a vague complaint and a defendable case when memories start shifting later.',\r\n    [\r\n      'Keep screenshots, emails, schedules, and written instructions together.',\r\n      'Write down what happened while it is still fresh.',\r\n      'Note who saw it, who said it, and whether anyone followed up.',\r\n      'Bring the record to your steward so they can see the timeline, not just the conclusion.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"846334b3-f17e-5550-a34f-e9a618b52df2","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Intake Triage: Is This a Grievance, an Investigatory Meeting, or Something Else?","body":"The first steward task is not to solve everything in one call. It is to classify the problem correctly. Figure out whether the member is facing possible discipline, a contract violation, an urgent safety issue, or a question that needs information before strategy.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Ask what happened, when it happened, and what management has already said or done.","Find out whether a meeting is scheduled, discipline is threatened, or a deadline is already running.","Separate immediate representation needs from longer grievance development.","End intake with the next step, the owner, and the time limit."],"direction":"","topics":["grievance"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":11,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-310","donor_type":"Mini-Lesson","donor_category":"Grievance","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(310, 'Stewards', 'Grievance', 'Intake Triage: Is This a Grievance, an Investigatory Meeting, or Something Else?',\r\n    'The first steward task is not to solve everything in one call. It is to classify the problem correctly. Figure out whether the member is facing possible discipline, a contract violation, an urgent safety issue, or a question that needs information before strategy.',\r\n    [\r\n      'Ask what happened, when it happened, and what management has already said or done.',\r\n      'Find out whether a meeting is scheduled, discipline is threatened, or a deadline is already running.',\r\n      'Separate immediate representation needs from longer grievance development.',\r\n      'End intake with the next step, the owner, and the time limit.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"e84bdfc5-73da-5310-ad4f-5c48ecb6ddd6","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Information Requests: Ask for What You Need in Writing","body":"Stewards do not have to argue blind. If management is relying on records, directives, metrics, or witness accounts, request what you need in writing and tie it to representation. Clarity on the ask makes delay and denial easier to challenge later.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Name the documents, reports, schedules, or policies you need as specifically as you can.","State that the request is for union representation and contract enforcement.","Follow up verbal requests with a dated written summary.","Escalate when management stalls, partials the request, or refuses to explain the denial."],"direction":"","topics":["rights"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":12,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-311","donor_type":"Mini-Lesson","donor_category":"Rights","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(311, 'Stewards', 'Rights', 'Information Requests: Ask for What You Need in Writing',\r\n    'Stewards do not have to argue blind. If management is relying on records, directives, metrics, or witness accounts, request what you need in writing and tie it to representation. Clarity on the ask makes delay and denial easier to challenge later.',\r\n    [\r\n      'Name the documents, reports, schedules, or policies you need as specifically as you can.',\r\n      'State that the request is for union representation and contract enforcement.',\r\n      'Follow up verbal requests with a dated written summary.',\r\n      'Escalate when management stalls, partials the request, or refuses to explain the denial.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"f04a2d6f-117a-5e92-a4eb-36e26923467f","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Past Practice: How to Spot It and Prove It","body":"Past practice matters when the contract is silent or management suddenly changes an established pattern. To use it well, do not stop at saying \"this is how we have always done it.\" Build proof that the practice was repeated, known, and accepted over time.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Look for a consistent pattern, not a one-off exception.","Pin down how long the practice existed and who knew about it.","Collect schedules, emails, witness statements, and prior approvals that show the pattern.","Compare the old practice to the new management move so the change is concrete."],"direction":"","topics":["grievance"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":13,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-312","donor_type":"Mini-Lesson","donor_category":"Grievance","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(312, 'Stewards', 'Grievance', 'Past Practice: How to Spot It and Prove It',\r\n    'Past practice matters when the contract is silent or management suddenly changes an established pattern. To use it well, do not stop at saying \"this is how we have always done it.\" Build proof that the practice was repeated, known, and accepted over time.',\r\n    [\r\n      'Look for a consistent pattern, not a one-off exception.',\r\n      'Pin down how long the practice existed and who knew about it.',\r\n      'Collect schedules, emails, witness statements, and prior approvals that show the pattern.',\r\n      'Compare the old practice to the new management move so the change is concrete.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"eb17bf02-9237-599c-a33c-81bc6cf3af38","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Grievance Timelines: Miss the Date, Lose the Leverage","body":"A strong theory does not save a late grievance. Time limits shape leverage, and management knows it. Treat dates, notice points, and filing windows as part of the case itself, not admin work you can clean up later.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Identify the triggering event and the date the member knew or should have known about it.","Calendar every filing deadline and follow-up date immediately.","Move early when the facts are incomplete instead of waiting for a perfect record.","Write down timeline disputes so management cannot quietly rewrite when the clock started."],"direction":"","topics":["grievance"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":14,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-313","donor_type":"Mini-Lesson","donor_category":"Grievance","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(313, 'Stewards', 'Grievance', 'Grievance Timelines: Miss the Date, Lose the Leverage',\r\n    'A strong theory does not save a late grievance. Time limits shape leverage, and management knows it. Treat dates, notice points, and filing windows as part of the case itself, not admin work you can clean up later.',\r\n    [\r\n      'Identify the triggering event and the date the member knew or should have known about it.',\r\n      'Calendar every filing deadline and follow-up date immediately.',\r\n      'Move early when the facts are incomplete instead of waiting for a perfect record.',\r\n      'Write down timeline disputes so management cannot quietly rewrite when the clock started.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"90f9eb51-5876-5772-a5dc-44b9f1a2f18f","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Running the Meeting: Keep Management from Owning the Frame","body":"Management often tries to control the pace, the topic, and the assumptions in a meeting before the union gets its footing. A steward does not need to dominate the room, but does need to slow it down, define the purpose, and keep the discussion tied to the actual issue.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Start by clarifying the purpose of the meeting and whether discipline is possible.","Separate facts, accusations, and management conclusions instead of letting them blur together.","Use pauses, notes, and caucuses to prevent rushed answers.","Close with a summary of what was requested, what remains open, and what happens next."],"direction":"","topics":["negotiation"],"audience":"staff","tone":"","learning_outcome":"","factual_claims":true,"priority":15,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-314","donor_type":"Mini-Lesson","donor_category":"Negotiation","donor_audience":"Stewards","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(314, 'Stewards', 'Negotiation', 'Running the Meeting: Keep Management from Owning the Frame',\r\n    'Management often tries to control the pace, the topic, and the assumptions in a meeting before the union gets its footing. A steward does not need to dominate the room, but does need to slow it down, define the purpose, and keep the discussion tied to the actual issue.',\r\n    [\r\n      'Start by clarifying the purpose of the meeting and whether discipline is possible.',\r\n      'Separate facts, accusations, and management conclusions instead of letting them blur together.',\r\n      'Use pauses, notes, and caucuses to prevent rushed answers.',\r\n      'Close with a summary of what was requested, what remains open, and what happens next.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"bdebf3c1-7919-5384-ac37-d146aa91aecf","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Harassment or Retaliation: Start the Record the Same Day","body":"If a manager targets you after a complaint, union activity, leave request, or protected action, do not wait for the pattern to become obvious to everyone else. Start the record while the details are fresh so your steward can compare timing, treatment, and witnesses before the story gets diluted.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Write down dates, comments, schedule changes, directives, and who saw them.","Save texts, emails, screenshots, and any written follow-up.","Note what happened right before the treatment changed, including complaints or protected activity.","Tell your steward early even if you are not yet sure how to label it."],"direction":"","topics":["rights"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":16,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-315","donor_type":"Mini-Lesson","donor_category":"Rights","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(315, 'Members', 'Rights', 'Harassment or Retaliation: Start the Record the Same Day',\r\n    'If a manager targets you after a complaint, union activity, leave request, or protected action, do not wait for the pattern to become obvious to everyone else. Start the record while the details are fresh so your steward can compare timing, treatment, and witnesses before the story gets diluted.',\r\n    [\r\n      'Write down dates, comments, schedule changes, directives, and who saw them.',\r\n      'Save texts, emails, screenshots, and any written follow-up.',\r\n      'Note what happened right before the treatment changed, including complaints or protected activity.',\r\n      'Tell your steward early even if you are not yet sure how to label it.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"a5c7df65-a369-5d99-a7db-4958a2d92492","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Discipline Meeting Basics: Ask First, Answer Later","body":"If management calls you into a meeting that feels disciplinary, your first move is not to explain everything immediately. First find out what the meeting is about, whether discipline is possible, and whether you need union representation before the questioning goes further.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Ask what the meeting is about and whether it could lead to discipline.","Request union representation if discipline may be involved.","Do not guess, speculate, or fill silences to be helpful.","Write down who attended, what was said, and what documents were mentioned."],"direction":"","topics":["rights"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":17,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-316","donor_type":"Mini-Lesson","donor_category":"Rights","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(316, 'Members', 'Rights', 'Discipline Meeting Basics: Ask First, Answer Later',\r\n    'If management calls you into a meeting that feels disciplinary, your first move is not to explain everything immediately. First find out what the meeting is about, whether discipline is possible, and whether you need union representation before the questioning goes further.',\r\n    [\r\n      'Ask what the meeting is about and whether it could lead to discipline.',\r\n      'Request union representation if discipline may be involved.',\r\n      'Do not guess, speculate, or fill silences to be helpful.',\r\n      'Write down who attended, what was said, and what documents were mentioned.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"8348c3f8-547c-5e34-a3c4-139acd8f43f3","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"How to Read the Contract Without Getting Lost","body":"You do not need to memorize the whole contract to use it. Start with the problem in front of you, then look for the article or section that controls that topic. Read the exact wording, note any deadlines or exceptions, and bring the language to your steward with your question.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Start with the issue category: discipline, leave, workload, pay, schedule, or overtime.","Read the full clause, not just the heading or one sentence.","Watch for deadlines, management exceptions, and cross-references to other articles.","Save the article number so your steward can work from the same text."],"direction":"","topics":["general"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":18,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-317","donor_type":"Mini-Lesson","donor_category":"General","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(317, 'Members', 'General', 'How to Read the Contract Without Getting Lost',\r\n    'You do not need to memorize the whole contract to use it. Start with the problem in front of you, then look for the article or section that controls that topic. Read the exact wording, note any deadlines or exceptions, and bring the language to your steward with your question.',\r\n    [\r\n      'Start with the issue category: discipline, leave, workload, pay, schedule, or overtime.',\r\n      'Read the full clause, not just the heading or one sentence.',\r\n      'Watch for deadlines, management exceptions, and cross-references to other articles.',\r\n      'Save the article number so your steward can work from the same text.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"09ee42d0-bab7-5242-a6a3-f5f2c45a003a","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Loudermill Rights in Plain Language","body":"If you are a public employee facing major discipline, you generally have the right to notice of the charges and a chance to respond before the discipline is finalized. That does not replace union representation. It means management cannot skip straight to the outcome without giving you a meaningful chance to answer.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Ask for the charges, evidence, and meeting purpose in writing if possible.","Bring your steward in early so the response is not improvised alone.","Use the chance to respond carefully instead of reacting to every accusation on the spot.","Keep copies of the notice, timeline, and anything you submit back."],"direction":"","topics":["rights"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":19,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-318","donor_type":"Mini-Lesson","donor_category":"Rights","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(318, 'Members', 'Rights', 'Loudermill Rights in Plain Language',\r\n    'If you are a public employee facing major discipline, you generally have the right to notice of the charges and a chance to respond before the discipline is finalized. That does not replace union representation. It means management cannot skip straight to the outcome without giving you a meaningful chance to answer.',\r\n    [\r\n      'Ask for the charges, evidence, and meeting purpose in writing if possible.',\r\n      'Bring your steward in early so the response is not improvised alone.',\r\n      'Use the chance to respond carefully instead of reacting to every accusation on the spot.',\r\n      'Keep copies of the notice, timeline, and anything you submit back.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}},{"id":"cebe1b3d-c858-5f42-a047-b0eac3a4c07b","scope":"platform","organization_id":null,"chapter_id":null,"kind":"mini_lesson","locale":"en","locale_state":"draft","title":"Schedule Changes, Overtime, and Last-Minute Orders","body":"Schedule changes often get framed as routine management discretion even when notice rules, overtime rules, or past practice say otherwise. When the schedule moves suddenly, the important question is not only whether it was inconvenient. It is whether it violated a rule that can be challenged.","attribution":"","source":"","rights_note":"","review_note":"","bullets":["Save the old schedule, the new schedule, and when you were told about the change.","Note whether overtime, skipped breaks, leave conflicts, or short notice were involved.","Compare what happened to the contract language or normal past practice.","Contact your steward quickly because schedule disputes often depend on timing and records."],"direction":"","topics":["grievance"],"audience":"members","tone":"","learning_outcome":"","factual_claims":true,"priority":20,"is_default":false,"status":"draft","starts_at":null,"ends_at":null,"revision":1,"provenance":{"donor_sha":null,"donor_sha_note":"Commit unavailable: historical checkout has a stale Windows Git link.","donor_path":"lib/knowledge/knowledge-engine-seed.ts","donor_repo":"migration-infra-main-20260711","donor_content_id":"KE-319","donor_type":"Mini-Lesson","donor_category":"Grievance","donor_audience":"Members","donor_placement":"Hub Section","donor_sha256":"0cd6a184d0a3ad7a059e0f138277dbf2838a26fe79b3cabf3ad5502038fbc224","donor_git_blob_oid":"553914dc1287808a0f5967f6c7c7760fc7795550","raw_source_call":"L(319, 'Members', 'Grievance', 'Schedule Changes, Overtime, and Last-Minute Orders',\r\n    'Schedule changes often get framed as routine management discretion even when notice rules, overtime rules, or past practice say otherwise. When the schedule moves suddenly, the important question is not only whether it was inconvenient. It is whether it violated a rule that can be challenged.',\r\n    [\r\n      'Save the old schedule, the new schedule, and when you were told about the change.',\r\n      'Note whether overtime, skipped breaks, leave conflicts, or short notice were involved.',\r\n      'Compare what happened to the contract language or normal past practice.',\r\n      'Contact your steward quickly because schedule disputes often depend on timing and records.',\r\n    ])","recovery_note":"Unverified historical material. Attribution, currency and reuse rights require review before publication."}}]$recovered$::jsonb)
